//! 🪆️ Literal record binding protects completed fields and admits the borrowed domain census.
use super::*;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::RecordValue;
use semio_framework_dsl_record::DslField;
fn record(value:&FieldValue,last:u16)->Result<&RecordValue,ValueError>{let semio_framework_dsl_record::FieldValue::Record(value)=value else{return Err(invalid("native literal record required"))};closed(value,last)?;Ok(value)}
fn closed(value:&RecordValue,last:u16)->Result<(),ValueError>{if value.fields.keys().any(|id|*id>last){Err(invalid("native record has undeclared field"))}else{Ok(())}}
fn list(value:&RecordValue,id:u16)->Result<&[FieldValue],ValueError>{match value.get(id){Some(semio_framework_dsl_record::FieldValue::List(value))=>Ok(value),_=>Err(invalid("native literal ordered list required"))}}
fn scalar<T:DslField>(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<T,ValueError>{let out=c.scoped_stage(|c|{c.begin_stage(0)?;T::from_value_controlled(value.get(id).unwrap_or(&semio_framework_dsl_record::FieldValue::Absent),c)})?;c.step()?;Ok(out)}
fn optional_scalar<T:DslField>(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Option<T>,ValueError>{match value.get(id){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>{c.step()?;Ok(None)},Some(_)=>scalar(value,id,c).map(Some)}}
fn text(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{let Some(semio_framework_dsl_record::FieldValue::Text(value))=value.get(id)else{return Err(invalid("native literal text required"))};let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(c.copy_text(value)?,close::<String>);c.step()?;Ok(out.take())}
fn optional_text(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Option<String>,ValueError>{let out=match value.get(id){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>None,Some(semio_framework_dsl_record::FieldValue::Text(value))=>Some(c.copy_text(value)?),_=>return Err(invalid("native optional literal text required"))};let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(out,close::<Option<String>>);c.step()?;Ok(out.take())}
fn collection<T:RetireOwned>(values:&[FieldValue],c:&mut NativeDecodeControl<'_>,mut bind:impl FnMut(&FieldValue,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Vec<T>,ValueError>{c.scoped_stage(|c|{c.begin_stage(values.len())?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(c.allocate_vec(values.len())?,close::<Vec<T>>);for value in values{out.as_mut().push(c.scoped_stage(|c|{c.begin_stage(0)?;bind(value,c)})?);c.step()?;}Ok(out.take())})}
fn indices(value:&RecordValue,id:u16,c:&mut NativeDecodeControl<'_>)->Result<Vec<usize>,ValueError>{let out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(collection(list(value,id)?,c,|value,c|<usize as DslField>::from_value_controlled(value,c))?,close::<Vec<usize>>);c.step()?;Ok(out.take())}
fn rows(used:&mut usize,count:usize,maximum:usize)->Result<(),ValueError>{*used=used.checked_add(count).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"native owned row census overflow"))?;if *used>maximum{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"native owned row census exceeds caller limit"))}Ok(())}

fn node(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Node,ValueError>{let value=record(value,9)?;c.scoped_stage(|c|{c.begin_stage(10)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Node{kind:String::new(),integer:None,reference:None,text:None,name:None,negative:None,coefficient:None,scale:None,exponent:None,children:Vec::new()},close::<Node>);let n=out.as_mut();n.kind=text(value,0,c)?;n.integer=optional_scalar(value,1,c)?;n.reference=optional_scalar(value,2,c)?;n.text=optional_text(value,3,c)?;n.name=optional_text(value,4,c)?;n.negative=optional_scalar(value,5,c)?;n.coefficient=optional_text(value,6,c)?;n.scale=optional_scalar(value,7,c)?;n.exponent=optional_scalar(value,8,c)?;n.children=indices(value,9,c)?;Ok(out.take())})}
fn entity(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Entity,ValueError>{let value=record(value,1)?;c.scoped_stage(|c|{c.begin_stage(2)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Entity{name:String::new(),arguments:Vec::new()},close::<Entity>);out.as_mut().name=text(value,0,c)?;out.as_mut().arguments=indices(value,1,c)?;Ok(out.take())})}
fn instance(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Instance,ValueError>{let value=record(value,1)?;c.scoped_stage(|c|{c.begin_stage(2)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Instance{id:0,entities:Vec::new()},close::<Instance>);out.as_mut().id=scalar(value,0,c)?;out.as_mut().entities=collection(list(value,1)?,c,entity)?;c.step()?;Ok(out.take())})}
fn edm(value:&FieldValue,c:&mut NativeDecodeControl<'_>)->Result<Edm,ValueError>{let value=record(value,15)?;c.scoped_stage(|c|{c.begin_stage(16)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Edm{producer:String::new(),module:String::new(),creation_date:String::new(),host:String::new(),database:String::new(),database_version:String::new(),database_creation_date:String::new(),schema:String::new(),model:String::new(),model_creation_date:String::new(),header_model:String::new(),header_model_creation_date:String::new(),user:String::new(),group:String::new(),license:String::new(),options:String::new()},close::<Edm>);let f=out.as_mut();f.producer=text(value,0,c)?;f.module=text(value,1,c)?;f.creation_date=text(value,2,c)?;f.host=text(value,3,c)?;f.database=text(value,4,c)?;f.database_version=text(value,5,c)?;f.database_creation_date=text(value,6,c)?;f.schema=text(value,7,c)?;f.model=text(value,8,c)?;f.model_creation_date=text(value,9,c)?;f.header_model=text(value,10,c)?;f.header_model_creation_date=text(value,11,c)?;f.user=text(value,12,c)?;f.group=text(value,13,c)?;f.license=text(value,14,c)?;f.options=text(value,15,c)?;Ok(out.take())})}
fn census(value:&RecordValue,maximum:usize,c:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{closed(value,6)?;let mut used=2;rows(&mut used,0,maximum)?;for id in [1,2,3]{rows(&mut used,list(value,id)?.len(),maximum)?;}if !matches!(value.get(6),None|Some(FieldValue::Absent)){rows(&mut used,1,maximum)?;}c.scoped_stage(|c|{let instances=list(value,4)?;rows(&mut used,instances.len(),maximum)?;c.begin_stage(instances.len())?;for value in instances{let entities=list(record(value,1)?,1)?;rows(&mut used,entities.len(),maximum)?;c.scoped_stage(|c|{c.begin_stage(entities.len())?;for value in entities{rows(&mut used,list(record(value,1)?,1)?.len(),maximum)?;c.step()?;}Ok::<_,ValueError>(())})?;c.step()?;}Ok::<_,ValueError>(())})?;c.scoped_stage(|c|{let nodes=list(value,5)?;rows(&mut used,nodes.len(),maximum)?;c.begin_stage(nodes.len())?;for value in nodes{rows(&mut used,list(record(value,9)?,9)?.len(),maximum)?;c.step()?;}Ok(())})}
pub(super) fn frame(value:&RecordValue,c:&mut NativeDecodeControl<'_>,maximum:usize)->Result<Frame,ValueError>{census(value,maximum,c)?;c.scoped_stage(|c|{c.begin_stage(7)?;let mut out=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(Frame{schema:String::new(),file_description:Vec::new(),file_name:Vec::new(),file_schema:Vec::new(),instances:Vec::new(),values:Vec::new(),edm:None},close::<Frame>);let f=out.as_mut();f.schema=text(value,0,c)?;f.file_description=indices(value,1,c)?;f.file_name=indices(value,2,c)?;f.file_schema=indices(value,3,c)?;f.instances=collection(list(value,4)?,c,instance)?;c.step()?;f.values=collection(list(value,5)?,c,node)?;c.step()?;f.edm=match value.get(6){None|Some(semio_framework_dsl_record::FieldValue::Absent)=>None,Some(value)=>Some(edm(value,c)?)};c.step()?;Ok(out.take())})}
